  int wlnModalDialog::wlnAction(char* msg)
  {
    ItemVal ans,rval;

    ans = ShowModalDialog(msg,rval);
    if (ans == M_Cancel)
	return 0;

    // *** Add code to process dialog values here

    return ans == M_OK;
  }//wlnAction

