  //  SetValue(lblStartMsg, True, Hidden);
  //}
  int theLevel;
  //int i;
  //ItemVal indx;
  switch (id)		// We will do some things depending on value
    {
    case M_OK:
      //theLevel = 0;
      //indx = pickL1;
      //for(i = 0; i < 12; i++){
      //if(GetValue(pickL1 + i)){
      //theLevel = i * 3 + 1;
      //}
      //}
      theLevel = GetValue(lSpinner);
      if(!theLevel) theLevel = 1;
      ((wlnApp*)theApp)->startAtLevel(theLevel);
      break;
    case btnTestMDlg:
      {
	vNoticeDialog note(this);
	note.Notice("Test Dialog");
	break;
      }	//@V@:EndCase
    case cancelStart:
      {
	((wlnApp*)theApp)->Exit();
      }
    }//end switch
  vModalDialog::DialogCommand(id,retval,ctype);
